"""PROVENANCE.md: where every committed fixture comes from, with checksums."""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class Row:
    path: str  # relative to the data root
    source: str
    note: str


def render(rows: list[Row], data_root: Path) -> str:
    lines = [
        "# Fixture provenance",
        "",
        "Generated by `fixtures build`; do not edit. Every file is synthetic or",
        "freely redistributable; none holds real patient data.",
        "",
        "- `synthetic/`: built from scratch with pydicom; all patient fields",
        "  are synthetic.",
        "- `pydicom/`: unchanged copies of pydicom's bundled test files",
        "  (pydicom is MIT-licensed; the files come from public samples that",
        "  the pydicom authors downsized and de-identified).",
        "- `net/`: pynetdicom's encodings of the PDUs and DIMSE messages",
        "  dartdicom_net uses, with the inputs that built them (MIT).",
        "",
        "| File | Source | Notes | SHA-256 |",
        "|---|---|---|---|",
    ]
    for row in rows:
        digest = hashlib.sha256((data_root / row.path).read_bytes()).hexdigest()
        lines.append(f"| `{row.path}` | {row.source} | {row.note} | `{digest[:16]}…` |")
    return "\n".join(lines) + "\n"
